'use strict';
(()=>{
 const dialog=document.getElementById('book-dialog'),close=document.getElementById('book-close');if(!dialog||!close)return;
 const el=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const format=n=>Number(n).toLocaleString('de-DE',{maximumSignificantDigits:7}),qty=n=>new Intl.NumberFormat('de-DE',{notation:'compact',maximumFractionDigits:2}).format(n),percent=n=>Number(n).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:3})+'%';
 let active='',snapshot=null,history=[],timer=null,clock=null,abort=null,gen=0,trigger=null,lastError='',anchor=0,step=0;
 function parse(data){const row=values=>{if(!Array.isArray(values))throw Error('Ungültiges Orderbuch');return values.map(v=>({p:Number(v[0]),q:Number(v[1])})).filter(x=>Number.isFinite(x.p)&&Number.isFinite(x.q)&&x.p>0&&x.q>0)};const bids=row(data.b||data.bids).sort((a,b)=>b.p-a.p),asks=row(data.a||data.asks).sort((a,b)=>a.p-b.p),ts=Number(data.ts);if(!bids.length||!asks.length||bids[0].p>asks[0].p||!Number.isFinite(ts)||ts<=0)throw Error('Unvollständiges Orderbuch');return {bids,asks,ts,mid:(bids[0].p+asks[0].p)/2}}
 function impact(asks,budget){let remaining=budget,units=0;for(const x of asks){const used=Math.min(remaining,x.p*x.q);units+=used/x.p;remaining-=used;if(remaining<=1e-8)break}return remaining>1e-6||units<=0?null:(budget/units/asks[0].p-1)*100}
 function levels(s,window){const bids=s.bids.filter(x=>x.p>=s.mid*(1-window)).map(x=>({...x,value:x.p*x.q})),asks=s.asks.filter(x=>x.p<=s.mid*(1+window)).map(x=>({...x,value:x.p*x.q}));return {bids,asks,bidTotal:bids.reduce((n,x)=>n+x.value,0),askTotal:asks.reduce((n,x)=>n+x.value,0)}}
 function makeFrame(s,base,width,observed){function group(rows){const m=new Map();for(const x of rows){const k=Math.floor((x.p-base)/width);m.set(k,(m.get(k)||0)+x.p*x.q)}return m}return {observed,bids:group(s.bids),asks:group(s.asks),bidLow:s.bids.at(-1).p,bidHigh:s.bids[0].p,askLow:s.asks[0].p,askHigh:s.asks.at(-1).p}}
 function zones(frames,base,width,mid,window){const out=[];for(const side of ['bid','ask']){const keys=new Set();for(const f of frames)for(const k of (side==='bid'?f.bids:f.asks).keys())keys.add(k);for(const k of keys){const low=base+k*width,high=low+width,p=(low+high)/2;if((side==='bid'&&p>=mid)||(side==='ask'&&p<=mid)||Math.abs(p/mid-1)>window)continue;let total=0,n=0;for(const f of frames){const full=side==='bid'?low>=f.bidLow&&high<=f.bidHigh:low>=f.askLow&&high<=f.askHigh;if(!full)continue;total+=(side==='bid'?f.bids:f.asks).get(k)||0;n++}if(n)out.push({side,p,low,high,value:total/n,count:n,totalFrames:frames.length})}}return out}
 function state(){if(!active)return;if(lastError){el('book-state').textContent=lastError;dialog.classList.add('book-stale');return}if(!snapshot){dialog.classList.add('book-stale');el('book-state').textContent='◌ Orderbuch wird geladen …';return}let age=Math.max(0,(Date.now()-snapshot.ts)/1000);el('book-state').textContent=(age>15?'◌ Daten veraltet':'● Verbunden')+' · Snapshot vor '+Math.floor(age)+' Sek.';dialog.classList.toggle('book-stale',age>15)}
 function render(){if(!snapshot)return;const s=snapshot,window=Number(el('book-range').value),period=Number(el('book-period').value),l=levels(s,window),total=l.bidTotal+l.askTotal,spread=(s.asks[0].p-s.bids[0].p)/s.mid*100,cost=impact(s.asks,1200);el('book-spread').textContent=percent(spread);el('book-balance').textContent=total?Math.round(100*l.bidTotal/total)+' / '+Math.round(100*l.askTotal/total)+' %':'—';el('book-impact').textContent=cost===null?'Tiefe unzureichend':'+'+percent(cost);
  const frames=period?history:history.slice(-1),span=frames.length>1?Math.round((frames.at(-1).observed-frames[0].observed)/1000):0,gap=frames.some((f,i)=>i&&f.observed-frames[i-1].observed>15000);el('book-history').textContent=period?`Gesammelt: ${Math.floor(span/60)}:${String(span%60).padStart(2,'0')} / 15:00 · ${frames.length} Snapshots${gap?' · unterbrochen':''}`:'Aktueller Snapshot · Zonen';
  const bidEdge=(s.mid-s.bids.at(-1).p)/s.mid*100,askEdge=(s.asks.at(-1).p-s.mid)/s.mid*100,range=percent(window*100);el('book-coverage').textContent=`Gewählt: ±${range}. Aktuell geliefert: bis ${percent(bidEdge)} unter / ${percent(askEdge)} über Mitte (max. 1.000 Stufen je Seite). Nur vollständig abgedeckte Zonen werden gemittelt; weiter entfernte Tiefe kann fehlen. Das aktuelle Kauf-/Verkaufsverhältnis basiert auf den gelieferten Stufen, deren Abdeckung sich je Seite unterscheiden kann.`;
  const all=zones(frames,anchor,step,s.mid,window),best=side=>all.filter(x=>x.side===side).sort((a,b)=>b.value-a.value).slice(0,3),chosen=[...best('ask'),...best('bid')].sort((a,b)=>b.p-a.p),max=Math.max(1,...chosen.map(x=>x.value));el('book-levels').innerHTML=chosen.length?chosen.map(x=>`<div class="book-level ${x.side}"><span class="book-mark">${x.side==='ask'?'▼':'▲'}</span><span>${format(x.low)}–${format(x.high)} <small>USDT</small></span><b>${qty(x.value)} <small>USDT · Ø</small></b><span class="book-trend">${x.count}/${x.totalFrames}</span></div>`).join(''):'<div class="book-empty">Keine vollständig abgedeckten Zonen im gewählten Bereich. Die gelieferte Tiefe kann sehr eng sein.</div>';
  const record=typeof results!=='undefined'?results.find(r=>r.symbol===active):null;const bars=record&&typeof PulsePattern!=='undefined'?PulsePattern.aggregate(record.candles,15,target):[],series=bars.slice(-12).map(c=>+c[4]).filter(Number.isFinite);let min=Math.min(s.mid,...chosen.map(x=>x.p),...series),maxP=Math.max(s.mid,...chosen.map(x=>x.p),...series),pad=(maxP-min)*.12||s.mid*.001;min-=pad;maxP+=pad;const y=v=>20+(maxP-v)/(maxP-min)*200;
  let svg=`<svg viewBox="0 0 700 250" role="img" aria-label="15-Minuten-Kursverlauf und gemittelte Orderbuchzonen"><line x1="42" y1="${y(s.mid)}" x2="580" y2="${y(s.mid)}" stroke="#d1ded5" stroke-dasharray="5 5"/><text x="590" y="${y(s.mid)+3}" fill="#d1ded5" font-size="10">${format(s.mid)}</text>`;if(series.length>1)svg+=`<path d="${series.map((v,i)=>(i?'L':'M')+(45+i/(series.length-1)*355).toFixed(1)+','+y(v).toFixed(1)).join(' ')}" fill="none" stroke="#b8c9c0" stroke-width="1.5" opacity=".75"/>`;for(const x of chosen){const width=25+x.value/max*135,color=x.side==='ask'?'#f28183':'#bbf96b';svg+=`<line x1="${550-width}" x2="550" y1="${y(x.p)}" y2="${y(x.p)}" stroke="${color}" stroke-width="${3+x.value/max*7}" opacity=".85"/><text x="555" y="${y(x.p)+3}" fill="${color}" font-size="9">${format(x.p)}</text>`}el('book-chart').innerHTML=svg+'</svg>';state()}
 function stop(){gen++;clearTimeout(timer);clearInterval(clock);timer=clock=null;if(abort)abort.abort();abort=null;active='';snapshot=null;history=[];anchor=step=0;lastError='';dialog.classList.remove('book-stale')}
 async function poll(token){if(!active||token!==gen||document.hidden)return;const symbol=active;abort=new AbortController();const timeout=setTimeout(()=>abort.abort(),10000);try{const u='https://api.bitget.com/api/v3/market/orderbook?category=USDT-FUTURES&symbol='+encodeURIComponent(symbol)+'&limit=1000';const res=await fetch(u,{signal:abort.signal,cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);const json=await res.json();if(json.code!=='00000'||!json.data)throw Error('Ungültige API-Antwort');const next=parse(json.data);if(token!==gen)return;if(!snapshot||next.ts>=snapshot.ts){snapshot=next;if(!anchor){anchor=next.mid;step=anchor*.0005}const observed=Date.now();history.push(makeFrame(next,anchor,step,observed));history=history.filter(h=>observed-h.observed<=900000);lastError='';render()}}catch(e){if(token!==gen)return;lastError='◌ Verbindung eingeschränkt · erneuter Versuch';if(!snapshot){el('book-chart').innerHTML='<div class="book-empty">Orderbuch zurzeit nicht verfügbar.</div>';el('book-levels').innerHTML=''}state()}finally{clearTimeout(timeout);if(token===gen){abort=null;timer=setTimeout(()=>poll(token),5000)}}}
 function start(symbol,button){if(!/^[A-Z0-9]{2,40}$/.test(symbol))return;stop();active=symbol;trigger=button;el('book-title').textContent=symbol+' · Orderbuch';el('book-chart').innerHTML='<div class="book-empty">Orderbuch wird geladen …</div>';el('book-levels').innerHTML='';el('book-coverage').textContent='';el('book-history').textContent='Sammle Daten …';['book-spread','book-balance','book-impact'].forEach(id=>el(id).textContent='—');dialog.classList.remove('book-stale');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');state();clock=setInterval(state,1000);poll(gen)}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-book-symbol]');if(b)start(b.dataset.bookSymbol,b)});close.addEventListener('click',()=>{if(typeof dialog.close==='function')dialog.close();else{dialog.removeAttribute('open');stop();if(trigger)trigger.focus()}});dialog.addEventListener('close',()=>{const old=trigger;stop();if(old&&old.isConnected)old.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog&&typeof dialog.close==='function')dialog.close()});['book-range','book-period'].forEach(id=>el(id).addEventListener('change',render));document.addEventListener('visibilitychange',()=>{if(!active)return;if(document.hidden){gen++;clearTimeout(timer);if(abort)abort.abort();lastError='◌ Pausiert · Dashboard nicht sichtbar';state()}else{lastError='';gen++;if(abort)abort.abort();abort=null;history=[];snapshot=null;anchor=step=0;el('book-history').textContent='Sammle Daten …';state();poll(gen)}});
 globalThis.PulseBook={parse,impact,levels,makeFrame,zones};
})();
